SELECT op.seq, COALESCE(upload.cycle_id, CASE WHEN op.status = 'failed' THEN op.cycle_id END), COALESCE(upload.row_id, CASE WHEN op.status = 'failed' THEN (SELECT row_id FROM op_row WHERE seq = op.seq ORDER BY pos LIMIT 1) END) FROM op LEFT JOIN sync_upload AS upload ON upload.transfer_id = op.transfer_id WHERE op.intent_state = 'ready' AND op.origin_kind = 'transfer'
